"<section><h2>\u672c\u6b21\u6d4b\u91cf</h2><button id=\"bench\" onclick=\"benchmark()\">\u81ea\u52a8\u6d4b\u5ef6\u8fdf</button><pre id=\"summary\">\u5c1a\u672a\u6d4b\u91cf</pre><pre id=\"history\">\u5c1a\u65e0\u8bb0\u5f55</pre><small>\u624b\u673a\u603b\u5f80\u8fd4\u5305\u542b\u65e0\u7ebf\u4f20\u8f93\uff1b\u677f\u7aef\u8017\u65f6\u5355\u5217\u3002\u6ca1\u6709\u7535\u8111\u8f6c\u53d1\u3002</small></section>\n"
"<script>\n"
"let sequence=0,session=Date.now().toString(36),history=[];\n"
"function id(){return 'p'+session+'_'+(++sequence)}\n"
"function record(item){history.push(item);history=history.slice(-30);document.querySelector('#history').textContent=JSON.stringify(history,null,2)}\n"
"async function call(path,method='GET',body,requestId=id(),phase='interactive'){\n"
" let begin=performance.now(),control=new AbortController(),timer=setTimeout(()=>control.abort(),65000);\n"
" try{let r=await fetch(path,{method,headers:{'X-EW-Key':document.querySelector('#key').value,'X-EW-ID':requestId,'Content-Type':'text/plain'},body,signal:control.signal,cache:'no-store'});\n"
" let v=await r.json();v.phone_rtt_ms=Math.round(performance.now()-begin);if(!r.ok||!v.ok)throw Error(v.error||('HTTP '+r.status));\n"
" record({phase,path,id:requestId,phone_rtt_ms:v.phone_rtt_ms,board_elapsed_ms:v.board_elapsed_ms});return v;\n"
" }catch(e){record({phase,path,id:requestId,phone_rtt_ms:Math.round(performance.now()-begin),error:String(e&&e.message||e)});throw e\n"
" }finally{clearTimeout(timer)}\n"
"}\n"
"async function state(){try{let v=await call('/api/state');document.querySelector('#status').textContent=JSON.stringify(v.data,null,2)}catch(e){document.querySelector('#status').textContent='\u8fde\u63a5\u5931\u8d25\uff1a'+e.message}}\n"
"async function profile(value){try{let v=await call('/api/profile','POST',value);document.querySelector('#action').textContent='\u8bbe\u5907\u5df2\u786e\u8ba4\uff1a'+v.data.profile+'\\n\u624b\u673a\u5f80\u8fd4 '+v.phone_rtt_ms+' ms\uff1b\u677f\u7aef '+v.board_elapsed_ms+' ms';await state()}catch(e){document.querySelector('#action').textContent='\u672a\u786e\u8ba4\uff1a'+e.message}}\n"
"async function ask(){let button=document.querySelector('#ask');button.disabled=true;document.querySelector('#reply').textContent='\u5f00\u53d1\u677f\u6b63\u5728\u8bf7\u6c42\u6a21\u578b\uff0c\u654f\u611f\u5ea6\u64cd\u4f5c\u4ecd\u53ef\u4f7f\u7528\u2026';try{let v=await call('/api/ask','POST',document.querySelector('#question').value);document.querySelector('#reply').textContent=v.data.reply+'\\n\\n\u624b\u673a\u5f80\u8fd4 '+v.phone_rtt_ms+' ms\uff1b\u677f\u7aef '+v.board_elapsed_ms+' ms'}catch(e){document.querySelector('#reply').textContent='\u95ee\u7b54\u672a\u5b8c\u6210\uff1a'+e.message}finally{button.disabled=false}}\n"
"async function benchmark(){let button=document.querySelector('#bench'),s=document.querySelector('#summary');button.disabled=true;s.textContent='\u6b63\u5728\u6d4b\u91cf\uff0c\u8bf7\u7b49\u5f85\u2026';let states=[],profiles=[],control,answer,mayNeedRestore=false,restore=null,error='';const median=a=>a.slice().sort((a,b)=>a-b)[Math.floor(a.length/2)];\n"
" try{\n"
" for(let i=0;i<5;i++){let v=await call('/api/state','GET',undefined,undefined,'state');states.push(v.phone_rtt_ms)}\n"
" for(let value of ['early','standard','early','standard','standard']){mayNeedRestore=true;let v=await call('/api/profile','POST',value,undefined,'profile');if(v.data.profile!==value)throw Error('\u6863\u4f4d\u8bfb\u56de\u4e0d\u7b26');profiles.push(v.phone_rtt_ms)}\n"
" let model=call('/api/ask','POST','Reply only DIRECT_OK.',undefined,'model').then(v=>({value:v}),e=>({error:e}));await new Promise(r=>setTimeout(r,150));control=await call('/api/profile','POST','early',undefined,'control_during_model');restore=await call('/api/profile','POST','standard',undefined,'restore');if(restore.data.profile!=='standard')throw Error('\u6807\u51c6\u6863\u672a\u6062\u590d');mayNeedRestore=false;let modelResult=await model;if(modelResult.error)throw modelResult.error;answer=modelResult.value;\n"
" document.querySelector('#reply').textContent=answer.data.reply;\n"
" }catch(e){error=String(e&&e.message||e)}finally{\n"
" if(mayNeedRestore){try{restore=await call('/api/profile','POST','standard',undefined,'safety_restore');if(restore.data.profile!=='standard')throw Error('\u6807\u51c6\u6863\u8bfb\u56de\u4e0d\u7b26')}catch(e){error+=(error?'\uff1b':'')+'\u5b89\u5168\u6062\u590d\u5931\u8d25\uff1a'+String(e&&e.message||e)}}\n"
" button.disabled=false;\n"
" s.textContent=JSON.stringify({passed:!error&&!!answer,state_samples:states.length,state_median_ms:states.length?median(states):null,profile_samples:profiles.length,profile_median_ms:profiles.length?median(profiles):null,model_phone_ms:answer?answer.phone_rtt_ms:null,model_board_ms:answer?answer.board_elapsed_ms:null,control_during_model_ms:control?control.phone_rtt_ms:null,final_profile:restore&&restore.data?restore.data.profile:'unknown',error:error||undefined},null,2)\n"
" }}\n"
"</script></html>\n";
